       throw new Error(`Product ${productId} is not in the cart`);
     }
     if (quantity === 0) {
       this.lines.delete(productId);
       return;
     }
     line.quantity = quantity;
   }

   clear(): void {
     this.lines.clear();
   }

   get itemCount(): number {
     let total = 0;
     for (const line of this.lines.values()) total += line.quantity;
     return total;
   }

