  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws for empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe('mode "sum"', () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, fixed 200 → sum = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // 100% of 100 = 100, fixed min(100,100) = 100 → sum = 200 > 100
      expect(composite.computeDiscountCents(100)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("ignores policies returning negative (clamped to 0)", () => {
      const fakePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [fakePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe('mode "chain"', () => {
    it("compounds discounts sequentially", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500 → remaining 500
      // Second: 50% of 500 = 250 → remaining 250
      // Total discount: 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering affects result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // composite1: fixed 200 from 1000 → remaining 800, then 10% of 800 = 80 → total 280
      // composite2: 10% of 1000 = 100 → remaining 900, then min(200,900) = 200 → total 300
      expect(composite1.computeDiscountCents(1000)).toBe(280);
      expect(composite2.computeDiscountCents(1000)).toBe(300);
    });

    it("cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // First: min(600,1000) = 600 → remaining 400
      // Second: min(600,400) = 400 → remaining 0
      // Total: 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

