describe("WeightBasedShippingCalculator", () => {
  it("throws for empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("throws for bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws for non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("throws for negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 1000)).toBe(0);
  });

  it("selects first bracket that covers the weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g fits in first bracket
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
  });

  it("selects exact boundary bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // Exactly 500g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
  });

  it("moves to next bracket when just over boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 700, 1)], 1000)).toBe(600);
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 1000)).toBe(900);
  });

  it("sums weight across multiple lines and quantities", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 3000, costCents: 1000 },
    ]);
    // 200*3 + 500*2 = 1600 → second bracket
    const lines: CartLine[] = [makeLine("a", 200, 3), makeLine("b", 500, 2)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(1000);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart — line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    cart.add(product(), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for quantity <= 0", () => {
    const cart = new Cart();
    expect(() => cart.add(product(), 0)).toThrow(RangeError);
    expect(() => cart.add(product(), -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("remove returns true and removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(cart.remove("p1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow("not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", 1.5)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 3);
    cart.add(product({ id: "b", unitPriceCents: 200 }), 2);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900);
  });

  it("discount is applied after subtotal and clamped to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 9999, // exceeds subtotal
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
  });

  it("negative discount is clamped to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.1),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn((taxable, _region) => Math.floor(taxable * 0.08)),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 10); // subtotal 10000
    const totals = cart.totals();
    // discount = floor(10000 * 0.1) = 1000 → discounted = 9000
    // tax = floor(9000 * 0.08) = 720
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(720);
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(9000, "US");
  });

  it("shipping is computed with discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 500,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn((_lines, subtotal) => (subtotal >= 5000 ? 0 : 800)),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product({ unitPriceCents: 3000 }), 1); // subtotal 3000, discounted 2500
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(800);
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2500,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 100,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 50,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 1000-200 = 800; total = 800 + 100 + 50 = 950
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    expect(totals.taxCents).toBe(100);
    expect(totals.shippingCents).toBe(50);
    expect(totals.totalCents).toBe(950);
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("region defaults to US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn(() => 0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product(), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("uses custom region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn(() => 0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(product(), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("negative tax from calculator is clamped to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product(), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product(), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for a basic cart", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(800),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1600); // 800 * 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("timeout");
    });
  });

  describe("inventoryChecker", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when available is false", async () => {
      const cart = new Cart();
      cart.add(product(), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2, // less than requested 5
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("checks each line and stops at first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
          .mockResolvedValueOnce({ available: false }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("InventoryError has correct name property", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        expect((e as InventoryError).name).toBe("InventoryError");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 10000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 10000, no discount → taxable 10000, tax = floor(10000*0.1) = 1000
      expect(result.totals.taxCents).toBe(1000);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax is computed on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 2000 },
      });
      cart.add(product({ unitPriceCents: 10000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 10000, discount 2000 → discounted 8000, tax = floor(8000*0.1) = 800
      expect(result.totals.taxCents).toBe(800);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("service down");
    });

    it("throws for invalid async rate", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("combined collaborators", () => {
    it("price refresh + inventory check + async tax all compose", async () => {
      const cart = new Cart({
        shippingCalculator: { computeShippingCents: () => 500 },
      });
      cart.add(product({ id: "x", unitPriceCents: 100 }), 3);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // price refreshed to 2000 → subtotal = 2000*3 = 6000
      // no discount → discounted = 6000
      // tax = floor(6000 * 0.05) = 300
      // shipping = 500
      // total = 6000 + 300 + 500 = 6800
      expect(result.totals.subtotalCents).toBe(6000);
      expect(result.totals.taxCents).toBe(300);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(6800);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("x");
      expect(inventoryChecker.check).toHaveBeenCalledWith("x", 3);
    });

    it("inventory denial happens after price refresh", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      await expect(
        cart.checkout({ priceFetcher, inventoryChecker }),
      ).rejects.toThrow(InventoryError);
      // price fetcher still gets called
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalled();
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(750),
    };
    const lines = [makeLine("a", 500, 2)];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(750);
    expect(result[0]!.quantity).toBe(2);
  });

  it("preserves other product fields", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "a", name: "Alpha", unitPriceCents: 100, weightGrams: 300, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
