    expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("remove returns true and removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(cart.remove("p1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow("not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", 1.5)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product(), 2);
