import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for a basic cart", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(800),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1600); // 800 * 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("timeout");
    });
  });

  describe("inventoryChecker", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
    });

    it("throws InventoryError when available is false", async () => {
      const cart = new Cart();
      cart.add(product(), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2, // less than requested 5
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("checks each line and stops at first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
          .mockResolvedValueOnce({ available: false }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    });

    it("InventoryError has correct name property", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        expect((e as InventoryError).name).toBe("InventoryError");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 10000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 10000, no discount → taxable 10000, tax = floor(10000*0.1) = 1000
      expect(result.totals.taxCents).toBe(1000);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("async tax is computed on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 2000 },
      });
      cart.add(product({ unitPriceCents: 10000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 10000, discount 2000 → discounted 8000, tax = floor(8000*0.1) = 800
      expect(result.totals.taxCents).toBe(800);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("service down");
    });

    it("throws for invalid async rate", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("combined collaborators", () => {
    it("price refresh + inventory check + async tax all compose", async () => {
      const cart = new Cart({
        shippingCalculator: { computeShippingCents: () => 500 },
      });
      cart.add(product({ id: "x", unitPriceCents: 100 }), 3);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // price refreshed to 2000 → subtotal = 2000*3 = 6000
      // no discount → discounted = 6000
      // tax = floor(6000 * 0.05) = 300
      // shipping = 500
      // total = 6000 + 300 + 500 = 6800
      expect(result.totals.subtotalCents).toBe(6000);
      expect(result.totals.taxCents).toBe(300);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(6800);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("x");
      expect(inventoryChecker.check).toHaveBeenCalledWith("x", 3);
    });

    it("inventory denial happens after price refresh", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(999),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      await expect(
        cart.checkout({ priceFetcher, inventoryChecker }),
      ).rejects.toThrow(InventoryError);
      // price fetcher still gets called
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalled();
    });
  });
});
"}

