import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart — line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    cart.add(product(), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for quantity <= 0", () => {
    const cart = new Cart();
    expect(() => cart.add(product(), 0)).toThrow(RangeError);
    expect(() => cart.add(product(), -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("remove returns true and removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(cart.remove("p1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product(), 3);
    cart.updateQuantity("p1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow("not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product(), 1);
    expect(() => cart.updateQuantity("p1", 1.5)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 3);
    cart.add(product({ id: "b", unitPriceCents: 200 }), 2);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900);
  });

  it("discount is applied after subtotal and clamped to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 9999, // exceeds subtotal
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
  });

  it("negative discount is clamped to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.1),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn((taxable, _region) => Math.floor(taxable * 0.08)),
    };
    const cart = new Cart({ discountPolicy, taxCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 10); // subtotal 10000
    const totals = cart.totals();
    // discount = floor(10000 * 0.1) = 1000 → discounted = 9000
    // tax = floor(9000 * 0.08) = 720
    expect(totals.discountCents).toBe(1000);
    expect(totals.taxCents).toBe(720);
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(9000, "US");
  });

  it("shipping is computed with discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 500,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn((_lines, subtotal) => (subtotal >= 5000 ? 0 : 800)),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(product({ unitPriceCents: 3000 }), 1); // subtotal 3000, discounted 2500
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(800);
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2500,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => 100,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 50,
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(product({ unitPriceCents: 1000 }), 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 1000-200 = 800; total = 800 + 100 + 50 = 950
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    expect(totals.taxCents).toBe(100);
    expect(totals.shippingCents).toBe(50);
    expect(totals.totalCents).toBe(950);
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("region defaults to US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn(() => 0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product(), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("uses custom region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn(() => 0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(product(), 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("negative tax from calculator is clamped to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator });
    cart.add(product(), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product(), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

