import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty: number): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(750),
    };
    const lines = [makeLine("a", 500, 2)];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(750);
    expect(result[0]!.quantity).toBe(2);
  });

  it("preserves other product fields", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "a", name: "Alpha", unitPriceCents: 100, weightGrams: 300, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Alpha");
    expect(result[0]!.product.weightGrams).toBe(300);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(200);
  });

  it("calls fetcher for each line's product id", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(100)
        .mockResolvedValueOnce(200),
    };
    const lines = [makeLine("a", 50, 1), makeLine("b", 60, 1)];
    await refreshPrices(lines, fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([makeLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9.99),
    };
    await expect(refreshPrices([makeLine("a", 100, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("accepts price of 0", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(0),
    };
    const result = await refreshPrices([makeLine("a", 100, 1)], fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(0);
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher errors", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([makeLine("a", 100, 1)], fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });
});

describe("InventoryError", () => {
  it("has correct properties", () => {
    const err = new InventoryError("no stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("no stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
